_ordered_credit_stage_hook: Callable[[str, bool], None] | None = None
_preoptimizer_profile_stage_hook: Callable[[str, bool], None] | None = None


def set_ordered_credit_stage_hook(
    hook: Callable[[str, bool], None] | None,
) -> None:
    """Install diagnostic-only ordered-credit stage markers."""

    global _ordered_credit_stage_hook
    _ordered_credit_stage_hook = hook


def _mark_ordered_credit_stage(name: str, opening: bool) -> None:
    hook = _ordered_credit_stage_hook
    if hook is not None:
        hook(name, opening)


def set_preoptimizer_profile_stage_hook(
    hook: Callable[[str, bool], None] | None,
) -> None:
    """Install diagnostic-only top-level pre-optimizer stage markers."""

    global _preoptimizer_profile_stage_hook
    _preoptimizer_profile_stage_hook = hook


def _mark_preoptimizer_profile_stage(name: str, opening: bool) -> None:
    hook = _preoptimizer_profile_stage_hook
    if hook is not None:
        hook(name, opening)


def _memory_decay_weights(
    decay: Tensor,
    lag: Tensor,
    causal: Tensor,
) -> Tensor:
    return decay.pow(lag.clamp_min(0)).masked_fill(~causal, 0)


def _scoped_deterministic_index_add_(
    destination: Tensor,
    dim: int,
    index: Tensor,
    source: Tensor,
) -> Tensor:
    prior_enabled = torch.are_deterministic_algorithms_enabled()
    prior_warn_only = torch.is_deterministic_algorithms_warn_only_enabled()
    torch.use_deterministic_algorithms(True, warn_only=False)
    try:
        return destination.index_add_(dim, index, source)
    finally:
        torch.use_deterministic_algorithms(
            prior_enabled,
            warn_only=prior_warn_only,
        )


def _scoped_parameter_gradient_index_add_(
    parameter: Tensor,
    dim: int,
    index: Tensor,
    source: Tensor,
) -> Tensor:
    gradient = parameter.grad
    if gradient is None:
        raise RuntimeError("parameter gradient accumulator is missing")
    common_dtype = torch.promote_types(gradient.dtype, source.dtype)
    if gradient.dtype != common_dtype:
        gradient = gradient.to(common_dtype)
        parameter.grad = gradient
    return _scoped_deterministic_index_add_(
        gradient,
        dim,
        index,
        source.to(common_dtype),
    )


def _set_kronecker_input_projection_gradient(
    model: NativeReciprocalPCLanguageModel,
    token_ids: Tensor,
    embedding_gradient_source: Tensor,
) -> Tensor:
    projection = model.kronecker_input_projection
    byte_buffer = model._kronecker_byte_buffer
    length_buffer = model._kronecker_length_buffer
    if (
        projection is None
        or byte_buffer is None
        or length_buffer is None
        or model.kronecker_codec_sha256
        != model.config.kronecker_input_codec_sha256
    ):
        raise RuntimeError("Kronecker input codec or projection is missing")
    dense_base, sparse_index, sparse_source = (
        kronecker_projection_gradient_components(
            token_ids,
            byte_buffer,
            length_buffer,
            embedding_gradient_source,
        )
    )
    gradient = dense_base.unsqueeze(0).expand_as(projection).clone()
    _scoped_deterministic_index_add_(
        gradient,
        0,
        sparse_index,
        sparse_source,
    )
    projection.grad = gradient
    return gradient


def _set_bpe_ancestry_input_gradient(
    model: NativeReciprocalPCLanguageModel,
    token_ids: Tensor,
    embedding_gradient_source: Tensor,
) -> Tensor:
    table = model.bpe_ancestry_input_table
    indices = model._bpe_ancestry_indices
    counts = model._bpe_ancestry_counts
    inverse_sqrt_counts = model._bpe_ancestry_inverse_sqrt_counts
    if (
        table is None
        or indices is None
        or counts is None
        or inverse_sqrt_counts is None
        or model.bpe_ancestry_artifact_sha256
        != model.config.bpe_ancestry_input_artifact_sha256
    ):
        raise RuntimeError("BPE ancestry input geometry or table is missing")
    if getattr(model.config, "bpe_ancestry_fused_execution", False):
        from pfc.phase750_fused_bpe_ancestry_input import fused_ancestry_gradient

        gradient = fused_ancestry_gradient(
            token_ids,
            embedding_gradient_source,
            table,
            indices,
            counts,
            inverse_sqrt_counts,
        )
    else:
        ancestry_indices, ancestry_source = ancestry_gradient_components(
            token_ids,
            embedding_gradient_source,
            indices,
            counts,
            inverse_sqrt_counts,
        )
        gradient = torch.zeros_like(table)
        _scoped_deterministic_index_add_(
            gradient,
            0,
            ancestry_indices,
            ancestry_source,
        )
    table.grad = gradient
    return gradient


def _input_observation_gradient_source(
    model: NativeReciprocalPCLanguageModel,
    token_ids: Tensor,
    embedding_gradient_source: Tensor,
) -> Tensor:
    if model.config.row_energy_preserving_input_compander:
        raw_rows = model.embedding(token_ids).reshape_as(embedding_gradient_source)
        return row_energy_preserving_input_compander_vjp(
            raw_rows,
            embedding_gradient_source,
            rms_eps=model.config.rms_eps,
        )
    if model.config.energy_preserving_token_fingerprint_observation:
        packed_codes = model.energy_preserving_token_fingerprint_codes
        if packed_codes is None:
            raise RuntimeError("packed token fingerprints are missing")
        raw_rows = model.embedding(token_ids).reshape_as(embedding_gradient_source)
        fingerprints = unpack_token_fingerprints(
            packed_codes,
            token_ids,
            dtype=raw_rows.dtype,
        ).reshape_as(raw_rows)
        return energy_preserving_token_fingerprint_observation_vjp(
            raw_rows,
            fingerprints,
            embedding_gradient_source,
            rms_eps=model.config.rms_eps,
        )
    if model.config.self_dual_hadamard_token_observation_coupling:
        diagonals = model.token_observation_coupling_diagonals
        signs = model.fixed_ternary_hadamard_lexical_signs
        if diagonals is None or signs is None:
            raise RuntimeError("self-dual token observation coupling is incomplete")
        raw_rows = model.embedding(token_ids).reshape_as(embedding_gradient_source)
        result = self_dual_hadamard_token_observation_coupling_vjp(
            raw_rows,
            deployment_token_observation_coupling_diagonals(diagonals),
            signs,
            embedding_gradient_source,
        )
        diagonals.grad = result.diagonal_gradient.to(dtype=diagonals.dtype)
        return result.input_gradient
    if model.config.energy_preserving_self_bilinear_token_observation:
        raw_rows = model.embedding(token_ids).reshape_as(embedding_gradient_source)
        return energy_preserving_self_bilinear_token_observation_vjp(
            raw_rows,
            embedding_gradient_source,
            rms_eps=model.config.rms_eps,
        )
    if model.config.projected_self_bilinear_token_observation:
        projector = model.projected_self_bilinear_observation_matrix
        if projector is None:
            raise RuntimeError("projected self-bilinear matrix is missing")
        raw_rows = model.embedding(token_ids).reshape_as(embedding_gradient_source)
        result = projected_self_bilinear_token_observation_vjp(
            raw_rows,
            projector,
            embedding_gradient_source,
            rms_eps=model.config.rms_eps,
        )
        projector.grad = result.projector_gradient.to(dtype=projector.dtype)
        return result.input_gradient
    if model.config.self_gated_isometric_sign_token_observation:
        raw_rows = model.embedding(token_ids).reshape_as(embedding_gradient_source)
        return self_gated_isometric_sign_token_observation_vjp(
            raw_rows,
            embedding_gradient_source,
        )
    return embedding_gradient_source


def _host_metric_int(value: Tensor, *, defer: bool) -> Tensor | int:
    if value.ndim != 0:
        raise ValueError("host integer metric must be scalar")
    return value if defer else int(value.item())


def _exact_forward_safe_sqrt(value: Tensor, eps: float) -> Tensor:
    exact = value.sqrt()
    safe = value.clamp_min(eps**2).sqrt()
    return exact.detach() + safe - safe.detach()


def _cap_rms(value: Tensor, maximum: float, eps: float = 1e-8) -> Tensor:
    if maximum <= 0:
        return value
    rms = _exact_forward_safe_sqrt(
        value.float().square().mean(dim=-1, keepdim=True),
        eps,
    )
    scale = (maximum / rms.clamp_min(eps)).clamp(max=1.0)
    return value * scale.to(value.dtype)


def _bound_message_rms(
    value: Tensor,
    reference: Tensor,
    eps: float = 1e-8,
) -> Tensor:
    """Keep a routed local message within its originating task-message budget."""

    if value.shape[:-1] != reference.shape[:-1]:
        raise ValueError("local message and reference leading shapes must match")
    value_rms = _exact_forward_safe_sqrt(
        value.float().square().mean(dim=-1, keepdim=True),
        eps,
    )
    reference_rms = _exact_forward_safe_sqrt(
        reference.float().square().mean(dim=-1, keepdim=True),
        eps,
    )
    scale = (reference_rms / value_rms.clamp_min(eps)).clamp(max=1.0)
    return value * scale.to(value.dtype)


def _rms_norm_vjp(
    value: Tensor,
    weight: Tensor,
    output_direction: Tensor,
    eps: float,
) -> Tensor:
    """Closed-form local VJP for weighted RMS normalization."""

    inverse_rms = torch.rsqrt(value.square().mean(dim=-1, keepdim=True) + eps)
    weighted_direction = output_direction * weight
    radial = (weighted_direction * value).mean(dim=-1, keepdim=True)
    return weighted_direction * inverse_rms - value * inverse_rms.pow(3) * radial


def _rms_norm_vjp_with_inverse(
    value: Tensor,
    weight: Tensor,
    output_direction: Tensor,
    eps: float,
) -> tuple[Tensor, Tensor]:
    """Return the local VJP and its exact eager inverse-RMS intermediate."""

    inverse_rms = torch.rsqrt(value.square().mean(dim=-1, keepdim=True) + eps)
    weighted_direction = output_direction * weight
    radial = (weighted_direction * value).mean(dim=-1, keepdim=True)
    return (
        weighted_direction * inverse_rms - value * inverse_rms.pow(3) * radial,
        inverse_rms,
    )


def _rms_norm_jvp(
    value: Tensor,
    weight: Tensor,
    value_tangent: Tensor,
    eps: float,
) -> Tensor:
    """Closed-form local JVP for weighted RMS normalization."""

    inverse_rms = torch.rsqrt(value.square().mean(dim=-1, keepdim=True) + eps)
    radial_tangent = (value * value_tangent).mean(dim=-1, keepdim=True)
    return weight * (
        value_tangent * inverse_rms - value * inverse_rms.pow(3) * radial_tangent
    )


def _outer_mean(left: Tensor, right: Tensor) -> Tensor:
    """Layer-batched mean outer product.

    Inputs use [layers, samples, features]. Only activation layouts transpose;
    no forward parameter is read through a transpose.
    """

    if left.shape[:2] != right.shape[:2]:
        raise ValueError("outer-product sample dimensions must match")
    return torch.bmm(left.transpose(1, 2), right) / max(left.shape[1], 1)


def _grouped_outer_means(
    pairs: tuple[tuple[Tensor, Tensor], ...],
) -> tuple[Tensor, ...]:
    """Batch same-shape local outer products without changing sample order."""

    if not pairs:
        return ()
    left_shape = pairs[0][0].shape
    right_shape = pairs[0][1].shape
    if any(
        left.shape != left_shape or right.shape != right_shape
        for left, right in pairs
    ):
        raise ValueError("grouped outer products must have identical shapes")
    layers = left_shape[0]
    grouped = _outer_mean(
        torch.cat(tuple(left for left, _right in pairs), dim=0),
        torch.cat(tuple(right for _left, right in pairs), dim=0),
    )
    return tuple(grouped.split(layers, dim=0))


def _match_layer_rms(term: Tensor, reference: Tensor, eps: float = 1e-8) -> Tensor:
    """Match a local-rule term to the baseline association RMS per layer."""

    if term.shape != reference.shape or term.ndim < 2:
        raise ValueError("local-rule term and reference must share a layered shape")
    reduce_dims = tuple(range(1, term.ndim))
    term_rms = term.float().square().mean(dim=reduce_dims, keepdim=True).sqrt()
    reference_rms = (
        reference.float().square().mean(dim=reduce_dims, keepdim=True).sqrt()
    )
    scale = torch.where(
        term_rms > eps,
        reference_rms / term_rms.clamp_min(eps),
        torch.zeros_like(term_rms),
    )
    return term * scale.to(term.dtype)


def _synaptic_metaplasticity_genome(
    raw_genome: Tensor,
) -> tuple[Tensor, Tensor, Tensor, Tensor]:
    """Map the shared three-gene genome to bounded state/update controls."""

    if raw_genome.shape != (3,):
        raise ValueError("synaptic metaplasticity genome must have three genes")
    two = raw_genome.new_tensor(2.0)
    half_life = torch.pow(two, 6.0 + 6.0 * torch.tanh(raw_genome[0]))
    retention = torch.pow(two, -1.0 / half_life)
    fast_mix = torch.tanh(raw_genome[1])
    slow_mix = torch.tanh(raw_genome[2])
    return half_life, retention, fast_mix, slow_mix


def _recurrent_state_gate_genome(
    raw_genome: Tensor,
) -> tuple[Tensor, Tensor, Tensor, Tensor, Tensor, Tensor, Tensor]:
    """Map the shared five-gene genome to recurrent plasticity controls."""

    if raw_genome.shape != (5,):
        raise ValueError("recurrent state-gate genome must have five genes")
    two = raw_genome.new_tensor(2.0)
    half_life = torch.pow(two, 6.0 + 6.0 * torch.tanh(raw_genome[0]))
    retention = torch.pow(two, -1.0 / half_life)
    correction_mix = torch.tanh(raw_genome[1])
    gate_bias = raw_genome[2]
    state_scale = 4.0 * torch.tanh(raw_genome[3])
    alignment_scale = 4.0 * torch.tanh(raw_genome[4])
    static_gate = torch.sigmoid(gate_bias)
    return (
        half_life,
        retention,
        correction_mix,
        gate_bias,
        state_scale,
        alignment_scale,
        static_gate,
    )


def _alignment_recurrent_basis_genome(
    raw_genome: Tensor,
) -> tuple[Tensor, Tensor, Tensor, Tensor, Tensor, Tensor, Tensor, Tensor]:
    """Map the shared six-gene genome to signed basis-mixing controls."""

    if raw_genome.shape != (6,):
        raise ValueError("alignment-recurrent basis genome must have six genes")
    two = raw_genome.new_tensor(2.0)
    half_life = torch.pow(two, 6.0 + 6.0 * torch.tanh(raw_genome[0]))
    retention = torch.pow(two, -1.0 / half_life)
    fast_bias = raw_genome[1]
    static_fast_coefficient = torch.tanh(fast_bias)
    fast_state_scale = 4.0 * torch.tanh(raw_genome[2])
    fast_current_scale = 4.0 * torch.tanh(raw_genome[3])
    base_state_scale = 4.0 * torch.tanh(raw_genome[4])
    base_current_scale = 4.0 * torch.tanh(raw_genome[5])
    return (
        half_life,
        retention,
        fast_bias,
        static_fast_coefficient,
        fast_state_scale,
        fast_current_scale,
        base_state_scale,
        base_current_scale,
    )


_DUAL_TRACE_FIXED_FAST_BIAS = -1.7783440158234427
_DUAL_TRACE_FIXED_FAST_CURRENT_SCALE = -0.0026082630715162387
_DUAL_TRACE_FIXED_BASE_CURRENT_SCALE = -2.684793432793419


def _dual_trace_basis_router_genome(
    raw_genome: Tensor,
) -> tuple[Tensor, Tensor, Tensor, Tensor, Tensor, Tensor, Tensor, Tensor]:
    """Map six genes to separate agreement/conflict state controls."""

    if raw_genome.shape != (6,):
        raise ValueError("dual-trace basis router genome must have six genes")
    two = raw_genome.new_tensor(2.0)
    agreement_half_life = torch.pow(
        two,
        6.0 + 6.0 * torch.tanh(raw_genome[0]),
    )
    conflict_half_life = torch.pow(
        two,
        6.0 + 6.0 * torch.tanh(raw_genome[1]),
    )
    agreement_retention = torch.pow(two, -1.0 / agreement_half_life)
    conflict_retention = torch.pow(two, -1.0 / conflict_half_life)
    fast_agreement_scale = 4.0 * torch.tanh(raw_genome[2])
    fast_conflict_scale = 4.0 * torch.tanh(raw_genome[3])
    base_agreement_scale = 4.0 * torch.tanh(raw_genome[4])
    base_conflict_scale = 4.0 * torch.tanh(raw_genome[5])
    return (
        agreement_half_life,
        agreement_retention,
        conflict_half_life,
        conflict_retention,
        fast_agreement_scale,
        fast_conflict_scale,
        base_agreement_scale,
        base_conflict_scale,
    )


def _reverse_affine_credit(decay: Tensor, direction: Tensor) -> Tensor:
    """Parallel reverse scan for e[t] = d[t] + decay[t+1] * e[t+1]."""

    if decay.shape != direction.shape or decay.ndim != 4:
        raise ValueError(
            "decay and direction must share [layers, batch, sequence, width]"
        )
    layers, batch, sequence, width = decay.shape
    zero_step = torch.zeros_like(decay[:, :, :1])
    future_decay = torch.cat((decay[:, :, 1:], zero_step), dim=2)
    reverse_decay = future_decay.flip(2).reshape(layers * batch, sequence, width)
    reverse_direction = direction.flip(2).reshape(
        layers * batch,
        sequence,
        width,
    )
    reverse_credit = _affine_scan(
        reverse_decay,
        reverse_direction,
        torch.zeros(
            layers * batch,
            width,
            device=decay.device,
            dtype=decay.dtype,
        ),
    )
    return reverse_credit.reshape(layers, batch, sequence, width).flip(2)


def _rotating_affine_scan(
    decay: Tensor,
    write: Tensor,
    initial: Tensor,
    rotation: Tensor,
) -> Tensor:
    """Paired associative scan using fixed or token-conditioned rotations."""

    if decay.shape != write.shape or decay.ndim != 4:
        raise ValueError("decay and write must share [layer, batch, sequence, width]")
    layers, batch, sequence, width = decay.shape
    if width % 2:
        raise ValueError("rotating affine scan requires even width")
    if initial.shape != (layers, batch, width):
        raise ValueError("initial must have shape [layer, batch, width]")
    groups = layers * batch
    paired_decay = decay.reshape(groups, sequence, width // 2, 2)
    paired_write = write.reshape(groups, sequence, width // 2, 2)
    paired_initial = initial.reshape(groups, width // 2, 2)
    if rotation.shape == (layers, width // 2, 2):
        grouped_rotation = rotation.repeat_interleave(batch, dim=0).unsqueeze(1)
    elif rotation.shape == (layers, batch, sequence, width // 2, 2):
        grouped_rotation = rotation.reshape(
            groups,
            sequence,
            width // 2,
            2,
        )
    else:
        raise ValueError("rotation shape does not match temporal scan")
    matrix = _pair_recurrence_matrix(paired_decay, grouped_rotation)
    return _pair_affine_scan(
        matrix,
        paired_write,
        paired_initial,
    ).reshape(layers, batch, sequence, width)


def _reverse_rotating_affine_credit(
    decay: Tensor,
    direction: Tensor,
    rotation: Tensor,
) -> Tensor:
    """Exact reverse scan through paired temporal rotations."""

    if decay.shape != direction.shape or decay.ndim != 4:
        raise ValueError(
            "decay and direction must share [layer, batch, sequence, width]"
        )
    layers, batch, sequence, width = decay.shape
    if width % 2:
        raise ValueError("rotating affine credit requires even width")
    groups = layers * batch
    paired_decay = decay.reshape(groups, sequence, width // 2, 2)
    if rotation.shape == (layers, width // 2, 2):
        grouped_rotation = rotation.repeat_interleave(batch, dim=0).unsqueeze(1)
    elif rotation.shape == (layers, batch, sequence, width // 2, 2):
        grouped_rotation = rotation.reshape(
            groups,
            sequence,
            width // 2,
            2,
        )
    else:
        raise ValueError("rotation shape does not match temporal credit scan")
    forward_matrix = _pair_recurrence_matrix(
        paired_decay,
        grouped_rotation,
    )
    return _reverse_pair_matrix_credit(
        forward_matrix.reshape(
            layers,
            batch,
            sequence,
            width // 2,
            2,
            2,
        ),
        direction,
    )


def _pair_forward_eligibility_linear_gradient(
    matrix: Tensor,
    direction: Tensor,
    presynaptic: Tensor,
    postsynaptic_factor: Tensor,
) -> Tensor:
    """Contract exact forward pair-state eligibility for one linear stage."""

    if matrix.ndim != 5 or matrix.shape[-2:] != (2, 2):
        raise ValueError("matrix must have shape [batch, sequence, pair, 2, 2]")
    batch, sequence, pairs = matrix.shape[:3]
    if direction.shape != (batch, sequence, pairs, 2):
        raise ValueError("direction must have shape [batch, sequence, pair, 2]")
    if postsynaptic_factor.shape != direction.shape:
        raise ValueError("postsynaptic factor must match direction")
    if presynaptic.ndim != 3 or presynaptic.shape[:2] != (batch, sequence):
        raise ValueError("presynaptic must have shape [batch, sequence, input]")
    inputs = presynaptic.shape[-1]
    eligibility = torch.zeros(
        batch,
        pairs,
        inputs,
        2,
        2,
        device=matrix.device,
        dtype=matrix.dtype,
    )
    gradient = torch.zeros(
        inputs,
        pairs,
        2,
        device=matrix.device,
        dtype=matrix.dtype,
    )
    identity = torch.eye(2, device=matrix.device, dtype=matrix.dtype)
    for token in range(sequence):
        eligibility = torch.einsum(
            "bpicd,bpde->bpice",
            eligibility,
            matrix[:, token],
        )
        amplitude = (
            presynaptic[:, token, None, :, None]
            * postsynaptic_factor[:, token, :, None, :]
        )
        eligibility.add_(amplitude.unsqueeze(-1) * identity)
        gradient.add_(
            torch.einsum(
                "bpe,bpice->ipc",
                direction[:, token],
                eligibility,
            )
        )
    return gradient.reshape(inputs, pairs * 2)


def _pair_matrix_affine_scan(
    matrix: Tensor,
    write: Tensor,
    initial: Tensor,
) -> Tensor:
    """Scan explicit per-layer, per-batch paired transition matrices."""

    if matrix.ndim != 6 or matrix.shape[-2:] != (2, 2):
        raise ValueError("matrix must have shape [layer, batch, sequence, pair, 2, 2]")
    layers, batch, sequence, pairs = matrix.shape[:4]
    width = pairs * 2
    if write.shape != (layers, batch, sequence, width):
        raise ValueError("write shape does not match paired transition matrix")
    if initial.shape != (layers, batch, width):
        raise ValueError("initial shape does not match paired transition matrix")
    return _pair_affine_scan(
        matrix.reshape(layers * batch, sequence, pairs, 2, 2),
        write.reshape(layers * batch, sequence, pairs, 2),
        initial.reshape(layers * batch, pairs, 2),
    ).reshape(layers, batch, sequence, width)


def _reverse_pair_matrix_credit_eager(
    matrix: Tensor,
    direction: Tensor,
) -> Tensor:
    """Exact reverse scan through arbitrary paired affine transitions."""

    if matrix.ndim != 6 or matrix.shape[-2:] != (2, 2):
        raise ValueError("matrix must have shape [layer, batch, sequence, pair, 2, 2]")
    layers, batch, sequence, pairs = matrix.shape[:4]
    width = pairs * 2
    if direction.shape != (layers, batch, sequence, width):
        raise ValueError("direction shape does not match paired transition matrix")
    grouped_matrix = matrix.reshape(
        layers * batch,
        sequence,
        pairs,
        2,
        2,
    )
    paired_direction = direction.reshape(
        layers * batch,
        sequence,
        pairs,
        2,
    )
    zero_matrix = torch.zeros_like(grouped_matrix[:, :1])
    future_reverse_matrix = torch.cat(
        (
            grouped_matrix[:, 1:].transpose(-1, -2),
            zero_matrix,
        ),
        dim=1,
    )
    reverse_credit = _pair_affine_scan(
        future_reverse_matrix.flip(1),
        paired_direction.flip(1),
        torch.zeros(
            layers * batch,
            pairs,
            2,
            device=direction.device,
            dtype=direction.dtype,
        ),
    )
    return reverse_credit.reshape(layers, batch, sequence, width).flip(2)


def _reverse_pair_matrix_credit(
    matrix: Tensor,
    direction: Tensor,
) -> Tensor:
    """Dispatch exact reverse credit to the accepted CUDA implementation."""

    if (
        matrix.is_cuda
        and direction.is_cuda
        and matrix.dtype == torch.float32
        and direction.dtype == torch.float32
    ):
        from pfc.phase415_explicit_round_reverse_credit import (
            reverse_pair_matrix_credit_explicit_round,
        )

        return reverse_pair_matrix_credit_explicit_round(matrix, direction)
    return _reverse_pair_matrix_credit_eager(matrix, direction)


def _reverse_pair_matrix_credit_by_episode(
    matrix: Tensor,
    direction: Tensor,
    episode_width: int,
) -> Tensor:
    """Reverse paired recurrence independently inside fixed-width episodes."""

    if matrix.ndim != 6 or matrix.shape[-2:] != (2, 2):
        raise ValueError("matrix must have shape [layer, batch, sequence, pair, 2, 2]")
    layers, batch, sequence, pairs = matrix.shape[:4]
    width = pairs * 2
    if direction.shape != (layers, batch, sequence, width):
        raise ValueError("direction shape does not match paired transition matrix")
    if episode_width <= 0 or sequence % episode_width:
        raise ValueError("sequence must contain complete fixed-width episodes")
    episodes = sequence // episode_width
    episode_matrix = matrix.reshape(
        layers,
        batch * episodes,
        episode_width,
        pairs,
        2,
        2,
    )
    episode_direction = direction.reshape(
        layers,
        batch * episodes,
        episode_width,
        width,
    )
    return _reverse_pair_matrix_credit(
        episode_matrix,
        episode_direction,
    ).reshape(layers, batch, sequence, width)


