    def install_exact_hierarchical_bpe_hierarchy(
        self,
        payload: dict[str, object],
        *,
        artifact_sha256: str,
        expected_artifact_sha256: str,
        expected_tokenizer_sha256: str,
    ) -> None:
        if not self.config.exact_hierarchical_bpe_likelihood_credit:
            raise ValueError("exact hierarchical BPE credit is disabled")
        if self._exact_hierarchical_bpe_hierarchy is not None:
            raise RuntimeError("exact hierarchical BPE hierarchy already installed")
        from pfc.phase639_exact_hierarchical_bpe import hierarchy_from_payload

        self._exact_hierarchical_bpe_hierarchy = hierarchy_from_payload(
            payload,
            artifact_sha256=artifact_sha256,
            expected_artifact_sha256=expected_artifact_sha256,
            expected_tokenizer_sha256=expected_tokenizer_sha256,
            device=self.model.device,
        )
        self._exact_hierarchical_bpe_artifact_sha256 = artifact_sha256

