    @torch.no_grad()
    def refresh_predictive_rls_geometry(
        self,
        *,
        initialize_intrinsic_key: bool = False,
    ) -> None:
        if not self.config.predictive_rls_likelihood:
            raise RuntimeError("predictive RLS likelihood is disabled")
        from pfc.phase274_predictive_error_fast_weights import (
            PREDICTIVE_FAST_WEIGHT_RANK,
            build_predictive_error_geometry_covariance,
        )

        learned_key = self.model.predictive_future_error_key_projection
        if (
            self.config.intrinsic_key_aligned_predictive_codebook
            and not initialize_intrinsic_key
        ):
            if learned_key is None:
                raise RuntimeError("intrinsic future-error key projection is missing")
            basis = learned_key.detach()
            from pfc.phase433_intrinsic_key_aligned_codebook import (
                build_intrinsic_key_aligned_predictive_codebook,
            )

            codebook = build_intrinsic_key_aligned_predictive_codebook(
                self.model.decoder_matrix(),
                basis,
            )
        else:
            if not initialize_intrinsic_key:
                self._predictive_rls_post_initialization_eigensolver_calls += 1
            basis, codebook = build_predictive_error_geometry_covariance(
                self.model.decoder_matrix(),
                PREDICTIVE_FAST_WEIGHT_RANK,
            )
            if self.config.intrinsic_future_error_key_projection or (
                self.config.exact_vjp_credit and learned_key is not None
            ):
                if learned_key is None:
                    raise RuntimeError(
                        "intrinsic future-error key projection is missing"
                    )
                if initialize_intrinsic_key:
                    learned_key.copy_(basis.to(learned_key.dtype))
                basis = learned_key.detach()
        self._predictive_rls_basis.copy_(basis)
        self._predictive_rls_codebook.copy_(codebook)

    @torch.no_grad()
    def _causal_semantic_utility_signal(self, token_loss: Tensor) -> Tensor:
        """Pair each perturbed support block with its untouched future query loss."""

        if token_loss.ndim != 2:
            raise ValueError("causal semantic utility loss must be [batch, sequence]")
        batch, sequence = token_loss.shape
        if batch < 2:
            raise ValueError("causal semantic utility requires paired batch members")
        block = self.model.config.bounded_attention_window
        episode_width = 2 * block
        if sequence % episode_width:
            raise ValueError(
                "causal semantic utility requires complete support/query episodes"
            )
        episode_count = sequence // episode_width
        episodes = token_loss.detach().reshape(batch, episode_count, 2, block)
        query_loss = episodes[:, :, 1].mean(dim=-1)
        centered_query_loss = query_loss - query_loss.mean(dim=0, keepdim=True)

        positions = torch.arange(sequence, device=token_loss.device)
        episode_indices = torch.div(
            positions,
            episode_width,
            rounding_mode="floor",
        )
        support = positions.remainder(episode_width) < block
        batch_indices = torch.arange(batch, device=token_loss.device).unsqueeze(1)
        parity = (
            batch_indices + episode_indices.unsqueeze(0) + self.update_count
        ).remainder(2)
        signs = parity.to(token_loss.dtype).mul_(2.0).sub_(1.0)
        support_episode = episode_indices.unsqueeze(0).expand(batch, -1)
        paired_query_loss = centered_query_loss.gather(1, support_episode)
        return signs * paired_query_loss * support.to(token_loss.dtype).unsqueeze(0)

    @torch.no_grad()
    def _apply_local_update_rule(
        self,
        trainable: list[nn.Parameter],
        local_error_rms: Tensor | None = None,
    ) -> tuple[Tensor, Tensor, Tensor]:
        """Gate associations using a shared causal layer-local meta-rule."""

        model = self.model
        one = torch.ones((), device=model.device)
        if not self.config.local_update_rule:
            return one, one, one

        progress = torch.zeros_like(self._latest_local_progress)
        progress_scale = self.config.local_update_rule_progress_scale
        if progress_scale != 0:
            if local_error_rms is None:
                raise ValueError("progress rule requires layer-local error RMS")
            if local_error_rms.shape != self._local_error_ema.shape:
                raise ValueError("layer-local error RMS has wrong shape")
            current_error = local_error_rms.detach().float().clamp_min(1e-8)
            initialized = self._update_count > 0
            progress = torch.where(
                initialized,
                torch.log(self._local_error_ema.clamp_min(1e-8) / current_error).clamp(
                    min=-1.0, max=1.0
                ),
                progress,
            )
            decay = self.config.local_update_rule_error_ema_decay
            updated_ema = torch.lerp(
                self._local_error_ema,
                current_error,
                1.0 - decay,
            )
            self._local_error_ema.copy_(
                torch.where(initialized, updated_ema, current_error)
            )
            self._latest_local_error_rms.copy_(current_error)
        else:
            self._latest_local_error_rms.zero_()
        self._latest_local_progress.copy_(progress)

        age_denominator = torch.log(
            torch.tensor(33.0, device=model.device, dtype=torch.float32)
        )
        age = torch.log1p(self._update_count.float()) / age_denominator
        gate_sum = torch.zeros((), device=model.device)
        gate_count = 0
        gate_min = torch.full((), float("inf"), device=model.device)
        gate_max = torch.full((), float("-inf"), device=model.device)
        for parameter in trainable:
            gradient = parameter.grad
            if gradient is None:
                continue
            gradient_rms = gradient.float().square().mean().sqrt().clamp_min(1e-8)
            gradient_feature = torch.log1p(gradient.abs().float() / gradient_rms)
            gradient_feature.sub_(gradient_feature.mean())
            log_gate = (
                self.config.local_update_rule_bias
                + self.config.local_update_rule_gradient_scale * gradient_feature
                + self.config.local_update_rule_age_scale * age
            )
            if id(parameter) in self._visit_layerwise_parameter_ids:
                if parameter.ndim < 2 or parameter.shape[1] != model.config.depth:
                    raise RuntimeError("visit-layerwise parameter depth mismatch")
                layer_feature = torch.linspace(
                    -1.0,
                    1.0,
                    parameter.shape[1],
                    device=model.device,
                    dtype=torch.float32,
                ).reshape((1, -1) + (1,) * (parameter.ndim - 2))
                log_gate = log_gate + (
                    self.config.local_update_rule_layer_scale * layer_feature
                )
                progress_feature = progress.reshape(
                    (1, -1) + (1,) * (parameter.ndim - 2)
                )
                log_gate = log_gate + progress_scale * progress_feature
            elif id(parameter) in self._layerwise_parameter_ids:
                if parameter.shape[0] != model.config.depth:
                    raise RuntimeError("layerwise parameter depth mismatch")
                layer_feature = torch.linspace(
                    -1.0,
                    1.0,
                    parameter.shape[0],
                    device=model.device,
                    dtype=torch.float32,
                ).reshape((-1,) + (1,) * (parameter.ndim - 1))
                log_gate = log_gate + (
                    self.config.local_update_rule_layer_scale * layer_feature
                )
                progress_feature = progress.reshape((-1,) + (1,) * (parameter.ndim - 1))
                log_gate = log_gate + progress_scale * progress_feature
            gate = log_gate.clamp(
                min=-self.config.local_update_rule_log_gate_cap,
                max=self.config.local_update_rule_log_gate_cap,
            ).exp()
            gradient.mul_(gate.to(dtype=gradient.dtype))
            gate_sum.add_(gate.sum())
            gate_count += gate.numel()
            gate_min = torch.minimum(gate_min, gate.min())
            gate_max = torch.maximum(gate_max, gate.max())
        if gate_count == 0:
            return one, one, one
        return gate_sum / gate_count, gate_min, gate_max

    @torch.compiler.disable
    def _step_progress_optimizer_eager(self) -> None:
        """Avoid Torch's stateful-gradient optimizer compiler assertion."""

        self.optimizer.step()

    def _credit_tanh_derivative(self, value: Tensor) -> Tensor:
        derivative = 1.0 - value.square()
        floor = self.config.wide_credit_derivative_floor
        if floor > 0.0:
            derivative = derivative.clamp_min(floor)
        return derivative

    def _settling_candidate_derivative(
        self,
        candidate_pre: Tensor,
        candidate: Tensor,
    ) -> Tensor:
        if self.model.config.softsign_reciprocal_transition:
            return (1.0 + candidate_pre.abs()).reciprocal().square()
        return self._credit_tanh_derivative(candidate)

    def _temporal_prediction_pair(
        self,
        raw: Tensor,
        lower: Tensor,
        targets: Tensor,
    ) -> tuple[Tensor, Tensor]:
        if self.config.layerwise_target_embedding_objective:
            target_observation = self.model.embed_tokens(targets)
            return (
                raw,
                target_observation.unsqueeze(0).expand(
                    self.model.config.depth,
                    -1,
                    -1,
                    -1,
                ),
            )
        return raw[:, :, :-1], lower[:, :, 1:]

    @torch.no_grad()
    def reset_optimizer_state(self) -> None:
        """Reset task-local optimizer history without changing learned tensors."""

        self.optimizer.zero_grad(set_to_none=True)
        self.optimizer.state.clear()
        self._update_count.zero_()
        if self._forward_jacobian_probe_generator is not None:
            self._forward_jacobian_probe_generator.manual_seed(539)
        if self._forward_jacobian_probe_buffer is not None:
            self._forward_jacobian_probe_buffer.zero_()
        self._local_error_ema.zero_()
        self._latest_local_progress.zero_()
        self._latest_local_error_rms.zero_()
        self._metaplastic_generative_trace.zero_()
        self._metaplastic_reciprocal_trace.zero_()
        self._state_gate_generative_state.zero_()
        self._state_gate_reciprocal_state.zero_()
        self._dual_trace_generative_conflict_state.zero_()
        self._dual_trace_reciprocal_conflict_state.zero_()
        self._complex_fast_generative_trace.zero_()
        self._complex_fast_reciprocal_trace.zero_()
        self._complex_slow_generative_trace.zero_()
        self._complex_slow_reciprocal_trace.zero_()
        self._complex_synapse_support_update_count.zero_()
        if self._hadamard_row_switch_transition_count is not None:
            self._hadamard_row_switch_transition_count.zero_()
        if self._hadamard_row_switch_latest_transition_count is not None:
            self._hadamard_row_switch_latest_transition_count.zero_()
        for displacement in self._charged_held_query_previous_displacements.values():
            displacement.zero_()
        self._charged_held_query_displacement_initialized.zero_()
        if (
            self.config.online_action_utility_router
            or self.config.context_keyed_action_utility_router
            or self.config.pareto_margin_action_utility_router
        ):
            self._online_action_utility_gram.copy_(
                torch.eye(
                    10,
                    device=self._online_action_utility_gram.device,
                    dtype=torch.float32,
                )
            )
            self._online_action_utility_rhs.zero_()
            self._online_action_utility_previous_features.zero_()
        if self.config.pareto_margin_action_utility_router:
            self._pareto_margin_action_utility_gram.copy_(
                torch.eye(
                    10,
                    device=self._pareto_margin_action_utility_gram.device,
                    dtype=torch.float32,
                )
            )
            self._pareto_margin_action_utility_rhs.zero_()
            self._pareto_margin_action_utility_previous_features.zero_()
        self._online_action_utility_initialized.zero_()
        if self.config.outcome_code_action_responsibility_router:
            self._outcome_code_action_gram.copy_(
                torch.eye(
                    32,
                    device=self._outcome_code_action_gram.device,
                    dtype=torch.float32,
                )
            )
            self._outcome_code_action_rhs.zero_()
            self._outcome_code_action_previous_descriptor.zero_()
        self._outcome_code_action_initialized.zero_()
        if self.config.channelwise_eligibility_responsibility_router:
            self._channelwise_eligibility_gram.copy_(
                torch.eye(
                    32,
                    device=self._channelwise_eligibility_gram.device,
                    dtype=torch.float32,
                )
            )
            self._channelwise_eligibility_rhs.zero_()
            self._channelwise_eligibility_previous_descriptor.zero_()
        self._channelwise_eligibility_initialized.zero_()
        if self.config.compact_bilinear_eligibility_rule:
            self._compact_bilinear_memory.zero_()
            self._compact_bilinear_previous_descriptor.zero_()
            self._compact_bilinear_previous_features.zero_()
        self._compact_bilinear_initialized.zero_()
        if self.config.optimizer_integrated_outcome_responsibility:
            self._optimizer_integrated_outcome_gram.copy_(
                torch.eye(
                    32,
                    device=self._optimizer_integrated_outcome_gram.device,
                    dtype=torch.float32,
                )
            )
            self._optimizer_integrated_outcome_rhs.zero_()
            self._optimizer_integrated_outcome_previous_descriptor.zero_()
        self._optimizer_integrated_outcome_initialized.zero_()
        if (
            self.config.vectorized_componentwise_optimizer_integrated_responsibility
        ):
            self._componentwise_optimizer_gram.copy_(
                torch.eye(
                    32,
                    device=self._componentwise_optimizer_gram.device,
                    dtype=torch.float32,
                )
            )
            self._componentwise_optimizer_rhs.zero_()
            self._componentwise_optimizer_previous_descriptor.zero_()
        self._componentwise_optimizer_initialized.zero_()
        for gradient in self._causal_adamw_previous_optimizer_gradients.values():
            gradient.zero_()
        for displacement in (
            self._time_indexed_held_query_second_displacements.values()
        ):
            displacement.zero_()
        self._time_indexed_held_query_initialized_slot_count.zero_()

    def charged_held_query_state_bytes(self) -> int:
        if not self.config.charged_held_query_displacement_projection:
            return 0
        state_bytes = sum(
            displacement.numel() * displacement.element_size()
            for displacement in self._charged_held_query_previous_displacements.values()
        )
        if self.config.time_indexed_held_query_credit:
            state_bytes += sum(
                displacement.numel() * displacement.element_size()
                for displacement in (
                    self._time_indexed_held_query_second_displacements.values()
                )
            )
        state_bytes += self.causal_adamw_moment_state_bytes()
        return state_bytes

    def self_assembling_transition_state_bytes(self) -> int:
        return sum(
            parameter.numel() * parameter.element_size()
            for parameter in (
                self.sal_hidden_cross,
                self.sal_output_cross_transpose,
            )
            if parameter is not None
        )

    def block_walsh_self_assembly_state_bytes(self) -> int:
        return sum(
            parameter.numel() * parameter.element_size()
            for parameter in (
                self.block_walsh_hidden_coefficients,
                self.block_walsh_output_coefficients,
            )
            if parameter is not None
        )

    def low_rank_self_assembly_state_bytes(self) -> int:
        return sum(
            parameter.numel() * parameter.element_size()
            for parameter in (
                self.low_rank_hidden_core,
                self.low_rank_output_core,
            )
            if parameter is not None
        )

    def _held_query_owns_model_parameter(self, name: str) -> bool:
        model = self.model
        if self.config.forward_jacobian_reciprocal_credit:
            from pfc.phase756_forward_jacobian_credit import (
                TRANSITION_OWNED_PARAMETER_NAMES,
            )

            if name in TRANSITION_OWNED_PARAMETER_NAMES:
                return False
        if (
            (
                self.config.self_assembling_heterosynaptic_transition
                or self.config.block_walsh_diagonal_self_assembly
                or self.config.two_sided_low_rank_self_assembly
            )
            and name in {"ffn_in", "ffn_out"}
        ):
            return False
        return not (
            self.config.token_conditioned_predictive_read_gate
            and name == "predictive_read_gate_projection"
        ) and not (
            (
                model.config.contractive_ternary_reciprocal_butterfly_ffn
                or model.config.intrinsic_ternary_reciprocal_ffn
            )
            and name in {"ffn_in", "ffn_out"}
        ) and not (
            model.config.lifted_antisymmetric_reciprocal_ffn
            and name == "ffn_out"
        ) and not (
            model.config.ternary_tpc_rtrl_elementwise_transition
            and name.startswith("rglru_")
        ) and not (
            model.config.ordered_swiglu_rglru_carry
            and name.startswith("ordered_rglru_")
        ) and name not in {
            "full_bandwidth_value",
            "full_bandwidth_gate",
        } and not (
            self.config.source_separated_transition_compartments
            and name.startswith("consequence_ffn_")
        )

    def _held_query_applies_to_model_parameter(self, name: str) -> bool:
        if (
            self.config.reciprocal_guided_competitive_hebbian_magnitude
            and name in {"ffn_in", "ffn_out"}
        ):
            return False
        return self._held_query_owns_model_parameter(name)

