        if not (
            self.config.online_action_utility_router
            or self.config.context_keyed_action_utility_router
            or self.config.pareto_margin_action_utility_router
        ):
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._online_action_utility_gram,
                self._online_action_utility_rhs,
                self._online_action_utility_previous_features,
                self._online_action_utility_initialized,
            )
        )

