    def componentwise_optimizer_responsibility_state_bytes(self) -> int:
        if not (
            self.config.vectorized_componentwise_optimizer_integrated_responsibility
        ):
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._componentwise_optimizer_codebook,
                self._componentwise_optimizer_gram,
                self._componentwise_optimizer_rhs,
                self._componentwise_optimizer_previous_descriptor,
                self._componentwise_optimizer_initialized,
            )
        )

    def synaptic_metaplasticity_state_bytes(self) -> int:
        if not self.config.synaptic_metaplasticity:
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._metaplastic_genome,
                self._metaplastic_generative_trace,
                self._metaplastic_reciprocal_trace,
            )
        )

    def complex_synapse_agreement_state_bytes(self) -> int:
        if not self.config.complex_synapse_agreement_consolidation:
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._complex_fast_generative_trace,
                self._complex_fast_reciprocal_trace,
                self._complex_slow_generative_trace,
                self._complex_slow_reciprocal_trace,
                self._complex_synapse_support_update_count,
            )
        )

    def recurrent_state_gate_state_bytes(self) -> int:
        if not self.config.recurrent_state_gate:
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._state_gate_genome,
                self._state_gate_generative_state,
                self._state_gate_reciprocal_state,
            )
        )

    def alignment_recurrent_basis_state_bytes(self) -> int:
        if not self.config.alignment_recurrent_basis_mixer:
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._alignment_basis_genome,
                self._state_gate_generative_state,
                self._state_gate_reciprocal_state,
            )
        )

    def dual_trace_basis_router_state_bytes(self) -> int:
        if not self.config.dual_trace_basis_router:
            return 0
        return sum(
            value.numel() * value.element_size()
            for value in (
                self._dual_trace_basis_genome,
                self._state_gate_generative_state,
                self._state_gate_reciprocal_state,
                self._dual_trace_generative_conflict_state,
                self._dual_trace_reciprocal_conflict_state,
            )
        )

    def optimizer_state_bytes(self) -> int:
        if isinstance(self.optimizer, Celo2Optimizer):
            return self.optimizer.state_bytes()
        return sum(
            value.numel() * value.element_size()
            for state in self.optimizer.state.values()
            for value in state.values()
            if isinstance(value, Tensor)
        )

    def optimizer_tensor_state_bytes(self) -> int:
        """Optimizer tensor state excluding per-parameter scalar step counters."""

        return sum(
            value.numel() * value.element_size()
            for state in self.optimizer.state.values()
            for name, value in state.items()
            if name != "step" and isinstance(value, Tensor)
        )

    def _lexical_readout_inverse(self, direction: Tensor) -> Tensor:
        if not self.model.config.fixed_ternary_hadamard_lexical_predictor:
            return direction @ self.readout_feedback
        signs = self.model.fixed_ternary_hadamard_lexical_signs
        if signs is None:
            raise RuntimeError("fixed lexical Hadamard signs are missing")
        from pfc.phase788_fixed_ternary_hadamard import (
            fixed_ternary_hadamard_lexical_inverse,
        )

        return fixed_ternary_hadamard_lexical_inverse(direction, signs)

    @torch.no_grad()
    def _refresh_ste_hadamard_row_switches(self) -> None:
        carrier = self.hadamard_row_switch_carrier
        if carrier is None:
            return
        if (
            self._hadamard_row_switch_transition_count is None
            or self._hadamard_row_switch_latest_transition_count is None
        ):
            raise RuntimeError("Hadamard row-switch counters are missing")
        signs = self.model.fixed_ternary_hadamard_lexical_signs
        if signs is None:
            raise RuntimeError("fixed lexical Hadamard signs are missing")
        from pfc.phase813_ste_hadamard_switches import (
            ste_binary_hadamard_signs,
        )

        updated = ste_binary_hadamard_signs(carrier)
        transitions = (updated != signs).sum(dtype=torch.int64)
        signs.copy_(updated)
        self._hadamard_row_switch_latest_transition_count.copy_(transitions)
        self._hadamard_row_switch_transition_count.add_(transitions)

    @torch.no_grad()
    def _coinitialize_reciprocal_pairs(self) -> None:
        """Write forward matrices from reciprocal storage once at initialization.

        Subsequent local gradients are transpose-matched and use matched optimizer
        rates, so independently stored reciprocal pairs stay aligned without ever
        reading a forward parameter through its transpose.
        """

        model = self.model
        if model.decoder is not None:
            model.decoder.copy_(self.output_feedback.transpose(0, 1))
        if model.ternary_embedding is None:
            model.embedding.weight.copy_(self.output_feedback)
        else:
            dense_width = model.config.split_ternary_lexical_dense_width
            model.embedding.weight.copy_(self.output_feedback[:, :dense_width])
            model.ternary_embedding.weight.copy_(
                self.output_feedback[:, dense_width:]
            )
        if not model.config.fixed_ternary_hadamard_lexical_predictor:
            model.token_predictor.copy_(self.readout_feedback.transpose(0, 1))
        if model.depth_lexical_decoders is not None:
            if (
                model.depth_lexical_output_norms is None
                or self.depth_lexical_output_feedback is None
            ):
                raise RuntimeError("depth lexical endpoint is incomplete")
            if model.config.cozero_reciprocal_lexical_adapters:
                self.depth_lexical_output_feedback.zero_()
            else:
                self.depth_lexical_output_feedback.copy_(
                    self.output_feedback.unsqueeze(0).expand_as(
                        self.depth_lexical_output_feedback
                    )
                )
            if model.config.depth_wide_ternary_lexical_endpoint:
                if (
                    model.depth_lexical_predictors is None
                    or self.depth_lexical_readout_feedback is None
                ):
                    raise RuntimeError("depth lexical predictor bank is incomplete")
                self.depth_lexical_readout_feedback.copy_(
                    self.readout_feedback.unsqueeze(0).expand_as(
                        self.depth_lexical_readout_feedback
                    )
                )
                model.depth_lexical_decoders.copy_(
                    self.output_feedback.transpose(0, 1).unsqueeze(0).expand_as(
                        model.depth_lexical_decoders
                    )
                )
                model.depth_lexical_predictors.zero_()
            else:
                if (
                    model.depth_lexical_predictors is not None
                    or self.depth_lexical_readout_feedback is not None
                ):
                    raise RuntimeError("feature-ready lexical residual has predictors")
                model.depth_lexical_decoders.zero_()
            model.depth_lexical_output_norms.copy_(
                model.output_norm.unsqueeze(0).expand_as(
                    model.depth_lexical_output_norms
                )
            )
        if not (
            model.config.contractive_ternary_reciprocal_butterfly_ffn
            or model.config.intrinsic_ternary_reciprocal_ffn
            or model.config.ternary_tpc_rtrl_elementwise_transition
        ):
            if model.config.sign_lifted_dual_ternary_transition:
                if self.ffn_feedback_sign_other is None:
                    raise RuntimeError("sign-lifted reciprocal companion is missing")
                model.ffn_out.copy_(
                    torch.cat(
                        (
                            self.ffn_feedback.transpose(1, 2),
                            self.ffn_feedback_sign_other.transpose(1, 2),
                        ),
                        dim=1,
                    )
                )
            else:
                model.ffn_out.copy_(self.ffn_feedback.transpose(1, 2))
            if model.config.ternary_dale_quadrant_transition:
                if (
                    model.ffn_out_dale_other is None
                    or self.ffn_feedback_dale_other is None
                ):
                    raise RuntimeError("Dale reciprocal companion banks are missing")
                model.ffn_out_dale_other.copy_(
                    self.ffn_feedback_dale_other.transpose(-1, -2)
                )
        model.refresh_lifted_antisymmetric_reciprocal_cache()
        if model.ffn_routed_out is not None:
            if self.ffn_routed_feedback is None:
                raise RuntimeError("routed FFN output feedback is missing")
            model.ffn_routed_out.copy_(
                self.ffn_routed_feedback.transpose(-1, -2)
            )
        if model.ffn_expert_out is not None:
            if self.ffn_expert_feedback is None:
                raise RuntimeError("deterministic FFN expert feedback is missing")
            model.ffn_expert_out.copy_(
                self.ffn_expert_feedback.transpose(-1, -2)
            )
        model.generative.copy_(model.reciprocal.transpose(1, 2))
        model.candidate.copy_(self.candidate_feedback.transpose(1, 2))
        if (
            model.later_candidates is not None
            and self.later_candidate_feedback is not None
        ):
            model.later_candidates.copy_(
                self.later_candidate_feedback.transpose(-1, -2)
            )
        if (
            model.later_candidate_adapters is not None
            and self.later_candidate_adapter_feedback is not None
        ):
            model.later_candidate_adapters.copy_(self.later_candidate_adapter_feedback)
        if (
            model.later_candidate_adapter_down is not None
            and model.later_candidate_adapter_up is not None
            and self.later_candidate_adapter_down_feedback is not None
            and self.later_candidate_adapter_up_feedback is not None
        ):
            model.later_candidate_adapter_down.copy_(
                self.later_candidate_adapter_down_feedback.transpose(-1, -2)
            )
            model.later_candidate_adapter_up.copy_(
                self.later_candidate_adapter_up_feedback.transpose(-1, -2)
            )
        if (
            model.later_dual_stream_adapter_down is not None
            and model.later_dual_stream_adapter_up is not None
            and self.later_dual_stream_adapter_down_feedback is not None
            and self.later_dual_stream_adapter_up_feedback is not None
        ):
            model.later_dual_stream_adapter_down.copy_(
                self.later_dual_stream_adapter_down_feedback.transpose(-1, -2)
            )
            model.later_dual_stream_adapter_up.copy_(
                self.later_dual_stream_adapter_up_feedback.transpose(-1, -2)
            )
        if (
            model.persistent_transition_adapter_down is not None
            and model.persistent_transition_adapter_up is not None
            and self.persistent_transition_adapter_down_feedback is not None
            and self.persistent_transition_adapter_up_feedback is not None
        ):
            model.persistent_transition_adapter_down.copy_(
                self.persistent_transition_adapter_down_feedback.transpose(
                    -1,
                    -2,
                )
            )
            model.persistent_transition_adapter_up.copy_(
                self.persistent_transition_adapter_up_feedback.transpose(
                    -1,
                    -2,
                )
            )
        if (
            model.temporal_phase_down is not None
            and model.temporal_phase_up is not None
            and self.temporal_phase_down_feedback is not None
            and self.temporal_phase_up_feedback is not None
        ):
            model.temporal_phase_down.copy_(
                self.temporal_phase_down_feedback.transpose(-1, -2)
            )
            model.temporal_phase_up.copy_(
                self.temporal_phase_up_feedback.transpose(-1, -2)
            )
        if (
            model.pairwise_delta_down is not None
            and model.pairwise_delta_key_up is not None
            and model.pairwise_delta_erase_up is not None
            and self.pairwise_delta_down_feedback is not None
            and self.pairwise_delta_key_up_feedback is not None
            and self.pairwise_delta_erase_up_feedback is not None
        ):
            model.pairwise_delta_down.copy_(
                self.pairwise_delta_down_feedback.transpose(-1, -2)
            )
            model.pairwise_delta_key_up.copy_(
                self.pairwise_delta_key_up_feedback.transpose(-1, -2)
            )
            model.pairwise_delta_erase_up.copy_(
                self.pairwise_delta_erase_up_feedback.transpose(-1, -2)
            )

    @torch.no_grad()
    def _project_dual_stream_visit_adapters(self) -> None:
        for parameter in (
            self.model.later_dual_stream_adapter_down,
            self.model.later_dual_stream_adapter_up,
            self.later_dual_stream_adapter_down_feedback,
            self.later_dual_stream_adapter_up_feedback,
        ):
            if parameter is not None:
                parameter.clamp_min_(0.0)

    @property
    def feedback_parameters(self) -> tuple[nn.Parameter, ...]:
        parameters = (self.output_feedback,)
        if not self.model.config.fixed_ternary_hadamard_lexical_predictor:
            parameters = parameters + (self.readout_feedback,)
        parameters = parameters + (
            self.temporal_predictor,
            self.temporal_feedback,
            self.candidate_feedback,
            self.generative_feedback,
            self.reciprocal_feedback,
            self.transition_feedback,
            self.gate_feedback,
        )
        if not (
            self.model.config.contractive_ternary_reciprocal_butterfly_ffn
            or self.model.config.intrinsic_ternary_reciprocal_ffn
            or self.model.config.lifted_antisymmetric_reciprocal_ffn
            or self.model.config.ternary_tpc_rtrl_elementwise_transition
        ):
            parameters = parameters + (
                self.ffn_feedback,
                self.ffn_in_feedback,
            )
            if self.ffn_feedback_residual is not None:
                parameters = parameters + (self.ffn_feedback_residual,)
            if self.ffn_feedback_dale_other is not None:
                parameters = parameters + (self.ffn_feedback_dale_other,)
            if self.ffn_feedback_sign_other is not None:
                parameters = parameters + (self.ffn_feedback_sign_other,)
        elif self.model.config.lifted_antisymmetric_reciprocal_ffn:
            parameters = parameters + (self.ffn_in_feedback,)
        if self.consequence_ffn_feedback is not None:
            if self.consequence_ffn_in_feedback is None:
                raise RuntimeError("consequence FFN reciprocal mirrors are incomplete")
            parameters = parameters + (
                self.consequence_ffn_feedback,
                self.consequence_ffn_in_feedback,
            )
        if self.affine_reversible_scale_feedback is not None:
            parameters = parameters + (
                self.affine_reversible_scale_feedback,
            )
        if self.depth_lexical_output_feedback is not None:
            parameters = parameters + (self.depth_lexical_output_feedback,)
        if self.swiglu_lexical_output_feedback is not None:
            parameters = parameters + (self.swiglu_lexical_output_feedback,)
        if self.context_routed_lexical_residual_output_feedback is not None:
            parameters = parameters + (
                self.context_routed_lexical_residual_output_feedback,
            )
        if self.bounded_multiplicative_lexical_output_feedback is not None:
            parameters = parameters + (
                self.bounded_multiplicative_lexical_output_feedback,
            )
        if self.signed_square_lexical_output_feedback is not None:
            parameters = parameters + (
                self.signed_square_lexical_output_feedback,
            )
        if self.cross_channel_quadratic_lexical_output_feedback is not None:
            parameters = parameters + (
                self.cross_channel_quadratic_lexical_output_feedback,
            )
        if self.shared_base_ternary_delta_output_feedback is not None:
            parameters = parameters + (
                self.shared_base_ternary_delta_output_feedback,
            )
        if self.depth_lexical_readout_feedback is not None:
            parameters = parameters + (self.depth_lexical_readout_feedback,)
        if self.depth_innovation_readout_feedback is not None:
            parameters = parameters + (
                self.depth_innovation_readout_feedback,
            )
        if self.ffn_expert_feedback is not None:
            if self.ffn_expert_in_feedback is None:
                raise RuntimeError("deterministic FFN expert feedback is incomplete")
            parameters = parameters + (
                self.ffn_expert_feedback,
                self.ffn_expert_in_feedback,
            )
        if self.ffn_residual_expert_feedback is not None:
            parameters = parameters + (self.ffn_residual_expert_feedback,)
        if self.rank_one_residual_feedback is not None:
            parameters = parameters + (self.rank_one_residual_feedback,)
        if self.diagonal_swiglu_feedback is not None:
            parameters = parameters + (self.diagonal_swiglu_feedback,)
        if self.transition_write_gate_feedback is not None:
            parameters = parameters + (self.transition_write_gate_feedback,)
        if self.readout_projection_feedback is not None:
            parameters = parameters + (self.readout_projection_feedback,)
        if self.later_candidate_feedback is not None:
            parameters = parameters + (self.later_candidate_feedback,)
        if self.later_candidate_adapter_feedback is not None:
            parameters = parameters + (self.later_candidate_adapter_feedback,)
        if self.later_candidate_adapter_down_feedback is not None:
            parameters = parameters + (
                self.later_candidate_adapter_down_feedback,
                self.later_candidate_adapter_up_feedback,
            )
        if self.later_dual_stream_adapter_down_feedback is not None:
            parameters = parameters + (
                self.later_dual_stream_adapter_down_feedback,
                self.later_dual_stream_adapter_up_feedback,
            )
        if self.persistent_transition_adapter_down_feedback is not None:
            parameters = parameters + (
                self.persistent_transition_adapter_down_feedback,
                self.persistent_transition_adapter_up_feedback,
            )
        if self.temporal_phase_down_feedback is not None:
            parameters = parameters + (
                self.temporal_phase_down_feedback,
                self.temporal_phase_up_feedback,
            )
        if self.pairwise_delta_down_feedback is not None:
            parameters = parameters + (
                self.pairwise_delta_down_feedback,
                self.pairwise_delta_key_up_feedback,
                self.pairwise_delta_erase_up_feedback,
            )
        if self.bounded_attention_query_feedback is not None:
            parameters = parameters + (
                self.bounded_attention_query_feedback,
                self.bounded_attention_key_feedback,
                self.bounded_attention_value_feedback,
                self.bounded_attention_output_feedback,
            )
        if self.centered_feedback_credit_basis is not None:
            parameters = parameters + (self.centered_feedback_credit_basis,)
        return parameters

    def install_frozen_meta_teaching_controller(
        self,
        controller: ActivityFeedbackController,
        *,
        artifact_sha256: str,
    ) -> None:
        if not self.config.frozen_meta_teaching_signal:
            raise ValueError("trainer does not enable frozen meta teaching")
        if (
            controller.config.depth != self.model.config.depth
            or controller.config.width != self.model.config.width
        ):
            raise ValueError("meta-teaching controller model shape differs")
        if len(artifact_sha256) != 64 or any(
            character not in "0123456789abcdef" for character in artifact_sha256
        ):
            raise ValueError("meta-teaching controller SHA256 is invalid")
        controller.to(device=self.model.device, dtype=self.model.dtype)
        controller.eval()
        for parameter in controller.parameters():
            parameter.requires_grad_(False)
            parameter.grad = None
        self._frozen_meta_teaching_controller = controller
        self._frozen_meta_teaching_artifact_sha256 = artifact_sha256

    @property
    def frozen_meta_teaching_artifact_sha256(self) -> str | None:
        return self._frozen_meta_teaching_artifact_sha256

    def install_phase_conditioned_local_target_controller(
        self,
        controller: nn.Module,
        *,
        artifact_sha256: str,
    ) -> None:
        if not self.config.phase_conditioned_local_target:
            raise ValueError("trainer does not enable phase-conditioned local target")
        controller_config = getattr(controller, "config", None)
        if controller_config is None or (
            controller_config.depth != self.model.config.depth
            or controller_config.width != self.model.config.width
        ):
            raise ValueError("phase-conditioned controller model shape differs")
        if not callable(getattr(controller, "strict_local_target", None)):
            raise TypeError("phase-conditioned controller lacks strict_local_target")
        if len(artifact_sha256) != 64 or any(
            character not in "0123456789abcdef" for character in artifact_sha256
        ):
            raise ValueError("phase-conditioned controller SHA256 is invalid")
        controller.to(device=self.model.device, dtype=self.model.dtype)
        controller.eval()
        for parameter in controller.parameters():
            parameter.requires_grad_(False)
            parameter.grad = None
        self._phase_conditioned_local_target_controller = controller
        self._phase_conditioned_local_target_artifact_sha256 = artifact_sha256

    @property
    def phase_conditioned_local_target_artifact_sha256(self) -> str | None:
        return self._phase_conditioned_local_target_artifact_sha256

