    def load_state_dict(self, state: dict[str, object]) -> None:
        codec_sha256 = state.get("kronecker_input_codec_sha256")
        if self.model.config.kronecker_input_embedding:
            if codec_sha256 != self.model.config.kronecker_input_codec_sha256:
                raise ValueError("checkpoint Kronecker codec identity differs")
        elif codec_sha256 is not None:
            raise ValueError("checkpoint contains disabled Kronecker input")
        ancestry_artifact_sha256 = state.get(
            "bpe_ancestry_input_artifact_sha256"
        )
        ancestry_buffer_sha256 = state.get("bpe_ancestry_input_buffer_sha256")
        if self.model.config.bpe_ancestry_input_embedding:
            if (
                ancestry_artifact_sha256
                != self.model.config.bpe_ancestry_input_artifact_sha256
                or ancestry_artifact_sha256
                != self.model.bpe_ancestry_artifact_sha256
                or ancestry_buffer_sha256
                != self.model.bpe_ancestry_buffer_sha256
            ):
                raise ValueError("checkpoint BPE ancestry identity differs")
        elif (
            ancestry_artifact_sha256 is not None
            or ancestry_buffer_sha256 is not None
        ):
            raise ValueError("checkpoint contains disabled BPE ancestry input")
        hierarchy_sha256 = state.get("exact_hierarchical_bpe_artifact_sha256")
        if self.config.exact_hierarchical_bpe_likelihood_credit:
            stored_update_count = state.get("update_count")
            fresh_foundation = (
                hierarchy_sha256 is None
                and isinstance(stored_update_count, int)
                and stored_update_count == 0
            )
            if (
                not fresh_foundation
                and self._exact_hierarchical_bpe_hierarchy is None
            ):
                raise RuntimeError(
                    "install exact hierarchical BPE hierarchy before load"
                )
            if not fresh_foundation and hierarchy_sha256 != (
                self._exact_hierarchical_bpe_artifact_sha256
            ):
                raise ValueError(
                    "checkpoint hierarchical BPE artifact identity differs"
                )
        elif hierarchy_sha256 is not None:
            raise ValueError("checkpoint contains disabled hierarchical BPE credit")
        controller_state = state.get("frozen_meta_teaching_controller")
        controller_sha256 = state.get("frozen_meta_teaching_artifact_sha256")
        phase_controller_state = state.get("phase_conditioned_local_target_controller")
        phase_controller_sha256 = state.get(
            "phase_conditioned_local_target_artifact_sha256"
        )
        continual_phase_controller_state = state.get(
            "continual_phase_synaptic_write_controller"
        )
        continual_phase_controller_sha256 = state.get(
            "continual_phase_synaptic_write_artifact_sha256"
        )
        two_timescale_controller_state = state.get(
            "two_timescale_phase_write_controller"
        )
        two_timescale_controller_sha256 = state.get(
            "two_timescale_phase_write_artifact_sha256"
        )
        complex_synapse_controller_state = state.get(
            "complex_synapse_agreement_controller"
        )
        complex_synapse_controller_sha256 = state.get(
            "complex_synapse_agreement_artifact_sha256"
        )
        if self.config.frozen_meta_teaching_signal:
            if self._frozen_meta_teaching_controller is None:
                raise RuntimeError(
                    "install frozen meta-teaching controller before load"
                )
            if not isinstance(controller_state, dict):
                raise ValueError("checkpoint lacks frozen meta-teaching controller")
            if controller_sha256 != self._frozen_meta_teaching_artifact_sha256:
                raise ValueError("checkpoint meta-teaching controller identity differs")
            self._frozen_meta_teaching_controller.load_state_dict(controller_state)
            self._frozen_meta_teaching_controller.eval()
            for parameter in self._frozen_meta_teaching_controller.parameters():
                parameter.requires_grad_(False)
                parameter.grad = None
        elif controller_state is not None:
            raise ValueError("checkpoint contains disabled frozen meta teaching")
        if self.config.phase_conditioned_local_target:
            if self._phase_conditioned_local_target_controller is None:
                raise RuntimeError(
                    "install phase-conditioned local-target controller before load"
                )
            if not isinstance(phase_controller_state, dict):
                raise ValueError(
                    "checkpoint lacks phase-conditioned local-target controller"
                )
            if (
                phase_controller_sha256
                != self._phase_conditioned_local_target_artifact_sha256
            ):
                raise ValueError(
                    "checkpoint phase-conditioned controller identity differs"
                )
            self._phase_conditioned_local_target_controller.load_state_dict(
                phase_controller_state
            )
            self._phase_conditioned_local_target_controller.eval()
            for (
                parameter
            ) in self._phase_conditioned_local_target_controller.parameters():
                parameter.requires_grad_(False)
                parameter.grad = None
        elif phase_controller_state is not None:
            raise ValueError(
                "checkpoint contains disabled phase-conditioned local target"
            )
        if self.config.continual_phase_synaptic_write:
            if self._continual_phase_synaptic_write_controller is None:
                raise RuntimeError(
                    "install continual phase-write controller before load"
                )
            if not isinstance(continual_phase_controller_state, dict):
                raise ValueError("checkpoint lacks continual phase-write controller")
            if (
                continual_phase_controller_sha256
                != self._continual_phase_synaptic_write_artifact_sha256
            ):
                raise ValueError(
                    "checkpoint continual phase-write controller identity differs"
                )
            self._continual_phase_synaptic_write_controller.load_state_dict(
                continual_phase_controller_state
            )
            self._continual_phase_synaptic_write_controller.eval()
            for (
                parameter
            ) in self._continual_phase_synaptic_write_controller.parameters():
                parameter.requires_grad_(False)
                parameter.grad = None
        elif continual_phase_controller_state is not None:
            raise ValueError(
                "checkpoint contains disabled continual phase synaptic write"
            )
        if self.config.two_timescale_phase_write:
            if self._two_timescale_phase_write_controller is None:
                raise RuntimeError(
                    "install two-timescale phase-write controller before load"
                )
