        complex_fast_reciprocal_trace_change_rms = torch.zeros((), device=model.device)
        complex_slow_generative_trace_change_rms = torch.zeros((), device=model.device)
        complex_slow_reciprocal_trace_change_rms = torch.zeros((), device=model.device)
